import{_ as a,a0 as s,w as i,s as p,I as e,x as t,a1 as o,A as r,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"Cloudflare 有了一個新東西，它可以替代互聯網上煩人的驗證碼 | LCTT x X-CMD","titleTemplate":false,"description":"Cloudflare 有了一個新東西，它可以替代互聯網上煩人的驗證碼 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Cloudflare 有了一個新東西，它可以替代互聯網上煩人的驗證碼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Cloudflare 有了一個新東西，它可以替代互聯網上煩人的驗證碼 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220609 Cloudflare Has Something New to Replace Annoying CAPTCHAs on the Internet","title":"Cloudflare 有了一個新東西，它可以替代互聯網上煩人的驗證碼","tag":"202206","desc":""},"relativePath":"202206/20220609 Cloudflare Has Something New to Replace Annoying CAPTCHAs on the Internet.md","filePath":"[post].md"}'),d={name:"202206/20220609 Cloudflare Has Something New to Replace Annoying CAPTCHAs on the Internet.md"};function f(C,l,m,T,x,g){const n=s("Link");return i(),p("div",null,[l[23]||(l[23]=e("h1",{id:"cloudflare-有了一個新東西-它可以替代互聯網上煩人的驗證碼",tabindex:"-1"},[t("Cloudflare 有了一個新東西，它可以替代互聯網上煩人的驗證碼 "),e("a",{class:"header-anchor",href:"#cloudflare-有了一個新東西-它可以替代互聯網上煩人的驗證碼","aria-label":"Permalink to “Cloudflare 有了一個新東西，它可以替代互聯網上煩人的驗證碼”"},"​")],-1)),l[24]||(l[24]=e("p",null,[t("不想通過正確輸入 "),e("ruby",null,[t("驗證碼"),e("rt",null,"CAPTCHA")]),t(" 來證明自己是個人類嗎？Cloudflare 可能有了一個解決方案。")],-1)),l[25]||(l[25]=e("p",null,[e("img",{src:"https://news.itsfoss.com/wp-content/uploads/2022/06/cloudflare-private-access-tokens.jpg",alt:"Cloudflare"})],-1)),e("p",null,[l[1]||(l[1]=t("互聯網服務巨頭 Cloudflare 前兩天 ",-1)),o(n,{href:"https://blog.cloudflare.com/eliminating-captchas-on-iphones-and-macs-using-new-standard/"},{default:r(()=>[...l[0]||(l[0]=[t("宣佈了",-1)])]),_:1}),l[2]||(l[2]=t()),l[3]||(l[3]=e("ruby",null,[t("私有訪問令牌"),e("rt",null,"Private Access Tokens")],-1)),l[4]||(l[4]=t(" 功能。這項功能旨在減少你在網絡上看到的驗證碼數量，同時改善你的隱私。",-1))]),l[26]||(l[26]=u('<p>你可能已經發現，驗證碼在移動設備上是一種可怕的體驗。通常，它們會最終會佔據整個屏幕，有時甚至無法完成。</p><p>作為替代方案，網站可以選擇收集唯一識別數據，以證明你是人類。當然，從隱私的角度來看，這種做法是很糟糕的。如果這麼做，許多重視隱私的公司都幾乎無法避免他們受到 <ruby>殭屍攻擊<rt>bot attacks</rt></ruby>。</p><p>幸運的是，私有訪問令牌（PAT）的發佈將改變這一點。</p><h3 id="私有訪問令牌會產生什麼影響" tabindex="-1">私有訪問令牌會產生什麼影響？ <a class="header-anchor" href="#私有訪問令牌會產生什麼影響" aria-label="Permalink to “私有訪問令牌會產生什麼影響？”">​</a></h3><p>簡而言之，私有訪問令牌能夠做到下面這些事：</p><ul><li>在支持的設備上減少驗證碼數量</li><li>增強用户隱私</li><li>允許網站所有者確保訪問者來自真實設備</li></ul><p>然而，深入觀察，我們可以看到私有訪問令牌的影響力遠不止於此。若使用傳統的驗證碼，就有多個實體可以訪問你的數據。</p><p>首先，你正在訪問的網站知道你的 IP 地址和你正在訪問的 URL。當然，這些數據是建立連接所需的最低要求。此外，對於更高級的功能，網站還會發送一些用户代理（UA）數據，還好這些數據並不是唯一可識別的。</p><p>然而，另一方，也就是驗證碼提供者，卻可以收集更多的數據。與你要訪問的網站一樣，它也知道你的 IP 地址、用户代理數據和你訪問的 URL。不幸的是，除此之外，他們還會收集其他數據，例如你的設備信息和交互數據。如果把這些信息，與你之前完成驗證碼的時間聯繫起來，你就會驚訝的發現，他們可以建立一個非常詳細的屬於你的個人資料。</p><p>幸運的是，有了 Cloudflare 的私有訪問令牌，你就可以完全繞過驗證碼，從而阻止驗證碼提供者收集此類數據。</p><h3 id="私有訪問令牌是如何工作的" tabindex="-1">私有訪問令牌是如何工作的？ <a class="header-anchor" href="#私有訪問令牌是如何工作的" aria-label="Permalink to “私有訪問令牌是如何工作的？”">​</a></h3><p><img src="https://news.itsfoss.com/wp-content/uploads/2022/06/PAT-Data-transfer-chart-1024x650.png" alt=""></p><p>驗證碼的理念是集中儘可能多的數據，私人訪問令牌則恰恰相反，它將數據去中心化，因此任何一方都無法唯一識別你。在你提到數據共享之前，Cloudflare 就已經特別指出了，數據不會在各方之間共享。</p><p>當你訪問使用 Cloudflare 和私人訪問令牌的網站的時候，共有三方將處理你的數據的不同部分。</p><ol><li>網站。它只會知道你的 IP、URL 和用户代理，這也是建立連接所必需的。</li><li>你的設備製造商。他們只會知道那些用於驗證設備是否真實所需的設備數據，而不會知道你正在訪問哪個網站，或你的 IP 地址是什麼。驗證了你的設備後，他們將生成一個令牌，該令牌將發送到 Cloudflare。</li><li>Cloudflare。他們將收到這個令牌，令牌中不包含你的任何設備數據，只有製造商對它是正品的“保證”。他們知道的唯一其他數據，就是你正在訪問的網站，同樣，這是為你提供內容所必需的。</li></ol><p>通過這種方式，Cloudflare 無需接觸你的數據，就可以對“你是一個人”充滿信心。</p><h3 id="支持的操作系統-沒有-linux" tabindex="-1">支持的操作系統：沒有 Linux？ <a class="header-anchor" href="#支持的操作系統-沒有-linux" aria-label="Permalink to “支持的操作系統：沒有 Linux？”">​</a></h3><p>你可能已經意識到，私人訪問令牌需要特定的操作系統功能才能工作。目前，它們僅存在於蘋果最新的操作系統上，即 iOS 和 iPadOS 16，以及 macOS Ventura。這是因為蘋果的操作系統只在有限的硬件上運行，設備驗證會更加容易。</p><p>另一方面，Linux 是一種通用操作系統，旨在在各種硬件上運行。因此，我認為，在可預見的未來，它都不會支持私人訪問令牌。</p><p>回到蘋果，我想到私人訪問令牌也可能導致消費者維修設備的權利出現一些問題。例如，如果我用第三方的非正品電池更換了老舊的 iPhone 原裝電池，私人訪問令牌系統會特殊對待這種情況嗎？</p><p>如果是 Linux 手機呢？這些製造商，如 Pine64 和 Purism，可能沒有支持這樣一個系統的基礎設施。是否可以在這些上使用私人訪問令牌呢？</p>',21)),e("p",null,[l[6]||(l[6]=t("Cloudflare 在 ",-1)),o(n,{href:"https://blog.cloudflare.com/eliminating-captchas-on-iphones-and-macs-using-new-standard/"},{default:r(()=>[...l[5]||(l[5]=[t("公告",-1)])]),_:1}),l[7]||(l[7]=t(" 中提到：",-1))]),l[27]||(l[27]=e("blockquote",null,[e("p",null,"我們正在積極努力讓其他客户和設備製造商也使用私人訪問令牌框架。每當新客户開始使用它時，從該客户進入你網站的流量將自動開始要求令牌，你的訪問者將自動看到更少的驗證碼。")],-1)),l[28]||(l[28]=e("p",null,"因此，我們希望看到它被更多的設備和操作系統採用。你如何看待 Cloudflare 的私人訪問令牌呢？在下面的評論中發表你的看法吧！",-1)),l[29]||(l[29]=e("hr",null,null,-1)),e("p",null,[l[9]||(l[9]=t("via: ",-1)),o(n,{href:"https://news.itsfoss.com/cloudflare-pat/"},{default:r(()=>[...l[8]||(l[8]=[t("https://news.itsfoss.com/cloudflare-pat/",-1)])]),_:1})]),e("p",null,[l[14]||(l[14]=t("作者：",-1)),o(n,{href:"https://news.itsfoss.com/author/jacob/"},{default:r(()=>[...l[10]||(l[10]=[t("Jacob Crume",-1)])]),_:1}),l[15]||(l[15]=t(" 選題：",-1)),o(n,{href:"https://github.com/lkxed"},{default:r(()=>[...l[11]||(l[11]=[t("lkxed",-1)])]),_:1}),l[16]||(l[16]=t(" 譯者：",-1)),o(n,{href:"https://github.com/lkxed"},{default:r(()=>[...l[12]||(l[12]=[t("lkxed",-1)])]),_:1}),l[17]||(l[17]=t(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:r(()=>[...l[13]||(l[13]=[t("wxy",-1)])]),_:1})]),e("p",null,[l[20]||(l[20]=t("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...l[18]||(l[18]=[t("LCTT",-1)])]),_:1}),l[21]||(l[21]=t(" 原創編譯，",-1)),o(n,{href:"https://linux.cn/"},{default:r(()=>[...l[19]||(l[19]=[t("Linux中國",-1)])]),_:1}),l[22]||(l[22]=t(" 榮譽推出",-1))])])}const w=a(d,[["render",f]]);export{A as __pageData,w as default};
